import SwiftUI

@main
struct RunnerApp: App {
    var body: some Scene {
        WindowGroup {
            Text("Runner")
        }
    }
}

import XCTest

final class LongPressBookClubTests: XCTestCase {
    func testLongPressBookClub() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state == .notRunning {
            app.launch()
        } else {
            app.activate()
        }

        let bookClub = app.staticTexts.matching(NSPredicate(format: "label == 'Book Club'")).firstMatch
        XCTAssertTrue(bookClub.waitForExistence(timeout: 20), "Book Club room not found in chat list")

        bookClub.press(forDuration: 2.0)
        Thread.sleep(forTimeInterval: 2.0)
    }
}
